/* ALTIGUARD Command Center v0.2 — client controller */
const state = {
  workers:new Map(), zones:[], incidents:[], broadcasts:[], floorplans:[],
  selectedWorker:null, currentView:'overview', heat:null, map:null, markers:new Map(), zoneLayers:new Map(),
  drawing:false, drawingPoints:[], drawingLayer:null, watchId:null, connected:false, demo:false,
  telemetryTimer:null, refreshTimer:null, theme:localStorage.getItem('altiguard-theme')||'night',
  settings:{}, dashboard:null, analytics:null, lastSnapshot:null
};
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const api=async(path,options={})=>{const res=await fetch(path,{headers:{'Content-Type':'application/json',...(options.headers||{})},...options});let data=null;try{data=await res.json()}catch{}if(!res.ok)throw new Error(data?.error||`HTTP ${res.status}`);return data};
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const fmtTime=v=>v?new Date(v).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'}):'—';
const fmtDate=v=>v?new Date(v).toLocaleString():'—';
const num=(v,d=1)=>Number.isFinite(Number(v))?Number(v).toFixed(d):'—';
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const severityRank=s=>({CRITICAL:3,HIGH:2,WARNING:1,NORMAL:0}[s]??0);
const severityClass=s=>String(s||'NORMAL').toLowerCase();
function toast(message,type='info'){const el=document.createElement('div');el.className=`toast ${type}`;el.innerHTML=`<b>${type.toUpperCase()}</b><span>${esc(message)}</span>`;$('#toastStack').appendChild(el);setTimeout(()=>el.remove(),4500)}
function setConnection(ok,label=ok?'LIVE':'OFFLINE'){state.connected=ok;const b=$('#connectionBadge');b.textContent=label;b.className=`badge ${ok?'ok':'danger'}`}
function setTheme(theme){state.theme=theme;document.documentElement.dataset.theme=theme;localStorage.setItem('altiguard-theme',theme);$('#themeBtn').textContent=theme==='night'?'☼':'◐'}
function switchView(view){state.currentView=view;$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$$('.view').forEach(v=>v.classList.remove('active'));const target=$(`#view-${view}`);if(target)target.classList.add('active');if(view==='workers')renderWorkersPage();if(view==='incidents')renderIncidentsPage();if(view==='zones')renderZonesPage();if(view==='analytics')renderAnalyticsPage();if(view==='broadcast')renderBroadcastPage();if(view==='floorplans')renderFloorplansPage();if(view==='system')renderSystemPage()}
function statCard(label,value,sub,icon,kind='normal'){return `<article class="stat-card ${kind}"><div class="stat-icon">${icon}</div><div><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(sub)}</small></div></article>`}
function renderStats(){const d=state.dashboard||{};$('#stats').innerHTML=[statCard('TOTAL WORKERS',d.workers??state.workers.size,'Registered personnel','◉'),statCard('ONLINE',d.online??0,'Fresh telemetry','●','good'),statCard('OPEN INCIDENTS',d.openIncidents??state.incidents.filter(i=>!['CLOSED','RESOLVED'].includes(i.status)).length,'Require review','⚠',d.critical?'critical':'normal'),statCard('CRITICAL',d.critical??state.incidents.filter(i=>i.severity==='CRITICAL').length,'Safety engine','!',d.critical?'critical':'good')].join('')}
function workerStatus(w){if(!w.lastSeen)return 'OFFLINE';return Date.now()-new Date(w.lastSeen).getTime()>15000?'STALE':(w.status||'ONLINE')}
function renderWorkerRows(list=[...state.workers.values()]){return list.sort((a,b)=>String(a.name).localeCompare(String(b.name))).map(w=>{const st=workerStatus(w);const delta=Number.isFinite(Number(w.altitudeM))&&Number.isFinite(Number(w.referenceM))?Number(w.altitudeM)-Number(w.referenceM):null;return `<div class="worker-row" data-worker="${esc(w.id)}"><div class="worker-name"><div class="worker-avatar">${esc((w.name||'?').slice(0,1).toUpperCase())}</div><div><b>${esc(w.name)}</b><small>${esc(w.employeeCode)} · ${esc(w.role||'WORKER')}</small></div></div><span class="status ${st.toLowerCase()}">${st}</span><span>${num(w.altitudeM)} m</span><span class="delta ${delta!==null&&delta<0?'down':''}">${delta===null?'—':`${delta>=0?'+':''}${delta.toFixed(1)} m`}</span><span>${w.heartRate??'—'} bpm</span><span>${w.spo2??'—'}%</span><span>${w.batteryPct??'—'}%</span><button class="icon-btn inspect" data-id="${esc(w.id)}">›</button></div>`}).join('')||'<div class="empty">No workers registered.</div>'}
function renderWorkerTable(){const wrap=$('#workerTable');if(!wrap)return;wrap.innerHTML=`<div class="worker-head"><span>WORKER</span><span>STATUS</span><span>ALT</span><span>Δ REF</span><span>HR</span><span>SpO₂</span><span>BAT</span><span></span></div>${renderWorkerRows()}`;$$('.inspect',wrap).forEach(b=>b.onclick=()=>openWorker(b.dataset.id))}
function renderIncidentFeed(){const wrap=$('#incidentFeed');if(!wrap)return;const items=[...state.incidents].sort((a,b)=>severityRank(b.severity)-severityRank(a.severity)||new Date(b.createdAt)-new Date(a.createdAt)).slice(0,12);wrap.innerHTML=items.map(i=>`<article class="incident ${severityClass(i.severity)}"><div class="incident-line"><span class="severity-dot ${severityClass(i.severity)}"></span><b>${esc(i.type.replaceAll('_',' '))}</b><time>${fmtTime(i.createdAt)}</time></div><p>${esc(i.message)}</p><div class="incident-meta"><span>${esc(i.worker?.name||i.workerId||'Unknown worker')}</span><span>${esc(i.status||'OPEN')}</span></div></article>`).join('')||'<div class="empty">No active incidents.</div>'}
function markerIcon(status){const color=status==='ONLINE'?'#55f6bd':status==='STALE'?'#ffc857':'#ff5370';return L.divIcon({className:'worker-marker-wrap',html:`<div class="worker-marker" style="--marker:${color}"><span></span></div>`,iconSize:[24,24],iconAnchor:[12,12]})}
function popup(w){return `<div class="popup"><b>${esc(w.name)}</b><span>${esc(w.employeeCode)}</span><hr><div>Altitude <strong>${num(w.altitudeM)} m</strong></div><div>Reference <strong>${num(w.referenceM)} m</strong></div><div>HR <strong>${w.heartRate??'—'} bpm</strong></div><div>SpO₂ <strong>${w.spo2??'—'}%</strong></div><div>Battery <strong>${w.batteryPct??'—'}%</strong></div><button class="popup-btn" onclick="openWorker('${esc(w.id)}')">OPEN PROFILE</button></div>`}
function initMap(){if(state.map)return;state.map=L.map('map',{zoomControl:false,preferCanvas:true}).setView([20.7005,77.0085],16);L.control.zoom({position:'bottomright'}).addTo(state.map);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:20,attribution:'© OpenStreetMap contributors'}).addTo(state.map);state.map.on('click',handleMapClick);setTimeout(()=>state.map.invalidateSize(),200)}
function upsertMarker(w){if(!state.map||!Number.isFinite(Number(w.lat))||!Number.isFinite(Number(w.lng)))return;let m=state.markers.get(w.id);if(!m){m=L.marker([w.lat,w.lng],{icon:markerIcon(workerStatus(w))}).addTo(state.map);state.markers.set(w.id,m)}else{m.setLatLng([w.lat,w.lng]);m.setIcon(markerIcon(workerStatus(w)))}m.bindPopup(popup(w));m._altiguardId=w.id}
function removeMarker(id){const m=state.markers.get(id);if(m){m.remove();state.markers.delete(id)}}
function renderZones(){if(!state.map)return;for(const layer of state.zoneLayers.values())layer.remove();state.zoneLayers.clear();state.zones.forEach(z=>{if(!z.enabled)return;const points=(z.polygon||[]).map(p=>[Number(p[0]),Number(p[1])]);if(points.length<3)return;const layer=L.polygon(points,{color:z.kind==='RED'?'#ff416c':'#ffc857',fillColor:z.kind==='RED'?'#ff416c':'#ffc857',fillOpacity:.14,weight:2,dashArray:'6 5'}).addTo(state.map);layer.bindTooltip(`${esc(z.name)} · ${esc(z.severity||'CRITICAL')}`);state.zoneLayers.set(z.id,layer)})}
function handleMapClick(e){if(!state.drawing)return;state.drawingPoints.push([e.latlng.lat,e.latlng.lng]);if(state.drawingLayer)state.drawingLayer.remove();state.drawingLayer=L.polygon(state.drawingPoints,{color:'#ff416c',fillOpacity:.18,dashArray:'5 5'}).addTo(state.map);if(state.drawingPoints.length>=3)toast('Three or more points set. Click Draw red zone again to save.','info')}
async function startZoneDrawing(){if(state.drawing){if(state.drawingPoints.length<3){state.drawing=false;state.drawingPoints=[];state.drawingLayer?.remove();$('#drawZoneBtn').textContent='Draw red zone';return}const name=prompt('Red zone name');if(!name)return;try{const z=await api('/api/zones',{method:'POST',body:JSON.stringify({name,polygon:state.drawingPoints,kind:'RED',severity:'CRITICAL'})});state.zones.unshift(z);state.drawing=false;state.drawingPoints=[];state.drawingLayer?.remove();state.drawingLayer=null;$('#drawZoneBtn').textContent='Draw red zone';renderZones();renderZonesPage();toast('Red zone created','success')}catch(e){toast(e.message,'error')}return}state.drawing=true;state.drawingPoints=[];$('#drawZoneBtn').textContent='Finish zone';toast('Click the map to add polygon vertices.','info')}
async function loadAll(){try{const [workers,zones,incidents,dash,meta]=await Promise.all([api('/api/workers'),api('/api/zones'),api('/api/incidents'),api('/api/dashboard'),api('/api/meta')]);state.workers.clear();workers.forEach(w=>state.workers.set(w.id,w));state.zones=zones;state.incidents=incidents;state.dashboard=dash;state.lastSnapshot=meta;renderAll();setConnection(true,'LIVE')}catch(e){setConnection(false,'OFFLINE');toast(`Backend unavailable: ${e.message}`,'error')}}
function renderAll(){renderStats();renderWorkerTable();renderIncidentFeed();renderZones();renderCurrentPage()}
function renderCurrentPage(){if(state.currentView==='workers')renderWorkersPage();if(state.currentView==='incidents')renderIncidentsPage();if(state.currentView==='zones')renderZonesPage();if(state.currentView==='analytics')renderAnalyticsPage();if(state.currentView==='broadcast')renderBroadcastPage();if(state.currentView==='floorplans')renderFloorplansPage();if(state.currentView==='system')renderSystemPage()}
function renderWorkersPage(){const el=$('#view-workers');if(!el)return;el.innerHTML=`<div class="page-head"><div><span class="eyebrow">PERSONNEL</span><h2>Worker Registry</h2><p>Manage field identities, devices and reference levels.</p></div><button class="btn primary" onclick="openWorkerForm()">+ Register worker</button></div><section class="panel"><div class="toolbar"><input id="workerSearch" class="input" placeholder="Search name, code or role"><select id="workerFilter" class="input"><option value="ALL">All statuses</option><option>ONLINE</option><option>STALE</option><option>OFFLINE</option></select></div><div class="worker-list-table"><div class="worker-head"><span>WORKER</span><span>STATUS</span><span>ALT</span><span>Δ REF</span><span>HR</span><span>SpO₂</span><span>BAT</span><span></span></div><div id="workersPageRows">${renderWorkerRows()}</div></div></section>`;const filter=()=>{const q=$('#workerSearch').value.toLowerCase();const st=$('#workerFilter').value;const list=[...state.workers.values()].filter(w=>(!q||`${w.name} ${w.employeeCode} ${w.role}`.toLowerCase().includes(q))&&(st==='ALL'||workerStatus(w)===st));$('#workersPageRows').innerHTML=renderWorkerRows(list);$$('.inspect',el).forEach(b=>b.onclick=()=>openWorker(b.dataset.id))};$('#workerSearch').oninput=filter;$('#workerFilter').onchange=filter}
function renderIncidentsPage(){const el=$('#view-incidents');const items=[...state.incidents].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));el.innerHTML=`<div class="page-head"><div><span class="eyebrow">EVENT MANAGEMENT</span><h2>Incident Center</h2><p>Review, acknowledge and close safety events.</p></div><div class="filter-pills"><button class="pill active" data-filter="ALL">All</button><button class="pill" data-filter="CRITICAL">Critical</button><button class="pill" data-filter="OPEN">Open</button></div></div><section class="panel"><div id="incidentPageList" class="incident-grid">${renderIncidentCards(items)}</div></section>`;$$('.pill',el).forEach(p=>p.onclick=()=>{$$('.pill',el).forEach(x=>x.classList.remove('active'));p.classList.add('active');let f=p.dataset.filter;let list=items;if(f==='CRITICAL')list=items.filter(i=>i.severity==='CRITICAL');if(f==='OPEN')list=items.filter(i=>!['CLOSED','RESOLVED'].includes(i.status));$('#incidentPageList').innerHTML=renderIncidentCards(list)})}
function renderIncidentCards(items){return items.map(i=>`<article class="incident-card ${severityClass(i.severity)}"><div class="card-top"><span class="severity-chip ${severityClass(i.severity)}">${esc(i.severity)}</span><time>${fmtDate(i.createdAt)}</time></div><h3>${esc(i.type.replaceAll('_',' '))}</h3><p>${esc(i.message)}</p><dl><dt>Worker</dt><dd>${esc(i.worker?.name||i.workerId||'Unknown')}</dd><dt>Position</dt><dd>${num(i.lat,5)}, ${num(i.lng,5)}</dd><dt>Altitude</dt><dd>${num(i.altitudeM)} m</dd><dt>Status</dt><dd>${esc(i.status||'OPEN')}</dd></dl><div class="card-actions"><button class="btn small ghost" onclick="downloadReport('${esc(i.id)}')">PDF report</button>${i.status!=='ACKNOWLEDGED'&&i.status!=='CLOSED'?`<button class="btn small" onclick="ackIncident('${esc(i.id)}')">Acknowledge</button>`:''}${i.status!=='CLOSED'?`<button class="btn small danger-btn" onclick="closeIncident('${esc(i.id)}')">Close</button>`:''}</div></article>`).join('')||'<div class="empty">No incidents match this filter.</div>'}
function renderZonesPage(){const el=$('#view-zones');el.innerHTML=`<div class="page-head"><div><span class="eyebrow">SPATIAL CONTROL</span><h2>Exclusion Zones</h2><p>Polygonal areas enforced by the server-side geofence engine.</p></div><button class="btn primary" onclick="startZoneDrawing();switchView('overview')">+ Draw on map</button></div><section class="panel"><div class="zone-grid">${state.zones.map(z=>`<article class="zone-card"><div class="zone-shape"></div><div><b>${esc(z.name)}</b><small>${esc(z.kind)} · ${esc(z.severity)}</small><p>${esc(z.description||'No description')}</p></div><button class="icon-btn danger-icon" onclick="deleteZone('${esc(z.id)}')">×</button></article>`).join('')||'<div class="empty">No exclusion zones configured.</div>'}</div></section>`}
function renderAnalyticsPage(){const el=$('#view-analytics');el.innerHTML=`<div class="page-head"><div><span class="eyebrow">TELEMETRY INTELLIGENCE</span><h2>Operational Analytics</h2><p>Understand movement, incident frequency and data quality.</p></div><select id="analyticsHours" class="input"><option value="12">Last 12 hours</option><option value="24">Last 24 hours</option><option value="72">Last 72 hours</option><option value="168">Last 7 days</option></select></div><section class="analytics-grid"><div class="panel" id="analyticsSummary">Loading…</div><div class="panel"><div class="panel-head"><b>MOVEMENT HEATMAP</b><button class="btn small ghost" onclick="toggleHeatmap()">Toggle map</button></div><div class="chart-placeholder">Heatmap is available on the live spatial matrix.</div></div></section><section class="panel"><div class="panel-head"><b>INCIDENT DISTRIBUTION</b></div><div id="incidentBars" class="bars"></div></section>`;$('#analyticsHours').onchange=loadAnalytics;loadAnalytics()}
async function loadAnalytics(){try{state.analytics=await api(`/api/analytics/summary?hours=${$('#analyticsHours').value}`);const a=state.analytics;$('#analyticsSummary').innerHTML=`<div class="metric-large"><span>Telemetry points</span><strong>${a.telemetry}</strong><small>${a.hours} hour window</small></div><div class="metric-large"><span>Incidents</span><strong>${a.incidents}</strong><small>All severity levels</small></div>`;const entries=Object.entries(a.byType||{}).sort((x,y)=>y[1]-x[1]);$('#incidentBars').innerHTML=entries.map(([k,v])=>`<div class="bar-row"><span>${esc(k.replaceAll('_',' '))}</span><div><i style="width:${Math.min(100,v*10)}%"></i></div><b>${v}</b></div>`).join('')||'<div class="empty">No incidents in period.</div>'}catch(e){toast(e.message,'error')}}
function renderBroadcastPage(){const el=$('#view-broadcast');el.innerHTML=`<div class="page-head"><div><span class="eyebrow">TACTICAL COMMUNICATIONS</span><h2>Command Broadcasts</h2><p>Send operational instructions to connected worker clients.</p></div></div><section class="panel broadcast-composer"><textarea id="pageBroadcast" placeholder="Write a clear site instruction…"></textarea><div><select id="pagePriority" class="input"><option>NORMAL</option><option>HIGH</option><option>CRITICAL</option></select><button class="btn primary" onclick="sendPageBroadcast()">Transmit command</button></div></section><section class="panel"><div class="panel-head"><b>RECENT COMMANDS</b></div><div class="broadcast-list">${state.broadcasts.map(b=>`<article><span class="severity-chip ${severityClass(b.priority)}">${esc(b.priority)}</span><p>${esc(b.message)}</p><time>${fmtDate(b.createdAt)}</time></article>`).join('')||'<div class="empty">No broadcasts recorded in this session.</div>'}</div></section>`}
function renderFloorplansPage(){const el=$('#view-floorplans');el.innerHTML=`<div class="page-head"><div><span class="eyebrow">INDOOR CONTEXT</span><h2>Floorplan Overlays</h2><p>Prepare calibrated blueprint overlays for indoor work areas.</p></div></div><section class="panel"><div class="notice">Floorplan calibration requires a publicly reachable image URL and four map bounds. Keep the image aligned with known site coordinates.</div><div class="floor-form"><input id="fpName" class="input" placeholder="Floorplan name"><input id="fpUrl" class="input" placeholder="Image URL"><input id="fpNorth" class="input" placeholder="North latitude"><input id="fpSouth" class="input" placeholder="South latitude"><input id="fpEast" class="input" placeholder="East longitude"><input id="fpWest" class="input" placeholder="West longitude"><button class="btn primary" onclick="createFloorplan()">Add overlay</button></div></section>`}
function renderSystemPage(){const el=$('#view-system');el.innerHTML=`<div class="page-head"><div><span class="eyebrow">PLATFORM</span><h2>System Status</h2><p>Runtime health, feature flags and operational parameters.</p></div></div><section class="system-grid"><article class="panel"><h3>Backend</h3><div id="systemMeta">Loading…</div></article><article class="panel"><h3>Safety thresholds</h3><div class="settings-list"><label>Altitude drop threshold <input id="setAlt" class="input" type="number" value="5"></label><label>Stale telemetry timeout <input id="setStale" class="input" type="number" value="15"></label></div></article></section>`;loadSystemMeta()}
async function loadSystemMeta(){try{const m=state.lastSnapshot||await api('/api/meta');$('#systemMeta').innerHTML=`<dl><dt>Version</dt><dd>${esc(m.version)}</dd><dt>Started</dt><dd>${fmtDate(m.startedAt)}</dd><dt>Features</dt><dd>${m.features.map(esc).join(', ')}</dd></dl>`}catch(e){$('#systemMeta').textContent=e.message}}
async function openWorker(id){const w=state.workers.get(id);if(!w)return;state.selectedWorker=w;const hist=await api(`/api/telemetry/${encodeURIComponent(id)}/range?hours=8`).catch(()=>[]);const modal=$('#modalRoot');modal.innerHTML=`<div class="modal-backdrop" onclick="closeModal(event)"><section class="modal" onclick="event.stopPropagation()"><div class="modal-head"><div><span class="eyebrow">WORKER PROFILE</span><h2>${esc(w.name)}</h2><p>${esc(w.employeeCode)} · ${esc(w.role||'WORKER')}</p></div><button class="icon-btn" onclick="closeModal()">×</button></div><div class="profile-grid"><div class="profile-stat"><span>STATUS</span><b>${esc(workerStatus(w))}</b></div><div class="profile-stat"><span>ALTITUDE</span><b>${num(w.altitudeM)} m</b></div><div class="profile-stat"><span>REFERENCE</span><b>${num(w.referenceM)} m</b></div><div class="profile-stat"><span>HEART RATE</span><b>${w.heartRate??'—'} bpm</b></div><div class="profile-stat"><span>SpO₂</span><b>${w.spo2??'—'}%</b></div><div class="profile-stat"><span>BATTERY</span><b>${w.batteryPct??'—'}%</b></div></div><div class="telemetry-mini"><b>Recent telemetry: ${hist.length} points</b><div>${hist.slice(-10).map(t=>`<span>${fmtTime(t.createdAt)} · ${num(t.altitudeM)}m · ${t.heartRate??'—'}bpm</span>`).join('')||'No persisted history.'}</div></div><div class="modal-actions"><button class="btn danger-btn" onclick="deleteWorker('${esc(w.id)}')">Remove worker</button><button class="btn primary" onclick="closeModal()">Done</button></div></section></div>`}
function closeModal(e){if(!e||e.target===e.currentTarget||!e.target)$('#modalRoot').innerHTML=''}
function openWorkerForm(){const modal=$('#modalRoot');modal.innerHTML=`<div class="modal-backdrop" onclick="closeModal(event)"><section class="modal compact" onclick="event.stopPropagation()"><div class="modal-head"><div><span class="eyebrow">REGISTRATION</span><h2>Add worker</h2></div><button class="icon-btn" onclick="closeModal()">×</button></div><form id="workerForm" class="form-grid"><input name="name" class="input" required placeholder="Full name"><input name="employeeCode" class="input" required placeholder="Employee code"><input name="role" class="input" placeholder="Role" value="WORKER"><input name="referenceM" class="input" type="number" placeholder="Reference altitude (m)" value="0"><button class="btn primary" type="submit">Register</button></form></section></div>`;$('#workerForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e));try{const w=await api('/api/workers',{method:'POST',body:JSON.stringify({...d,referenceM:Number(d.referenceM||0)})});state.workers.set(w.id,w);renderAll();closeModal();toast('Worker registered','success')}catch(err){toast(err.message,'error')}}}
async function deleteWorker(id){if(!confirm('Remove this worker from the registry?'))return;try{await api(`/api/workers/${encodeURIComponent(id)}`,{method:'DELETE'});state.workers.delete(id);removeMarker(id);closeModal();renderAll();toast('Worker removed','success')}catch(e){toast(e.message,'error')}}
async function deleteZone(id){if(!confirm('Delete this exclusion zone?'))return;try{await api(`/api/zones/${encodeURIComponent(id)}`,{method:'DELETE'});state.zones=state.zones.filter(z=>z.id!==id);renderZones();renderZonesPage();toast('Zone deleted','success')}catch(e){toast(e.message,'error')}}
async function ackIncident(id){try{const i=await api(`/api/incidents/${encodeURIComponent(id)}/ack`,{method:'POST',body:'{}'});mergeIncident(i);renderAll();toast('Incident acknowledged','success')}catch(e){toast(e.message,'error')}}
async function closeIncident(id){try{const i=await api(`/api/incidents/${encodeURIComponent(id)}/close`,{method:'POST',body:'{}'});mergeIncident(i);renderAll();toast('Incident closed','success')}catch(e){toast(e.message,'error')}}
function mergeIncident(i){const idx=state.incidents.findIndex(x=>x.id===i.id);if(idx<0)state.incidents.unshift(i);else state.incidents[idx]={...state.incidents[idx],...i}}
function downloadReport(id){window.open(`/api/incidents/${encodeURIComponent(id)}/report.pdf`,'_blank','noopener')}
async function sendBroadcast(message,priority='NORMAL'){if(!message?.trim())return;try{const b=await api('/api/broadcast',{method:'POST',body:JSON.stringify({message:message.trim(),priority})});state.broadcasts.unshift(b);io.emit?.('local:none');toast('Command transmitted','success');renderBroadcastPage()}catch(e){toast(e.message,'error')}}
async function sendPageBroadcast(){await sendBroadcast($('#pageBroadcast').value,$('#pagePriority').value);$('#pageBroadcast').value=''}
async function createFloorplan(){const body={name:$('#fpName').value,imageUrl:$('#fpUrl').value,north:Number($('#fpNorth').value),south:Number($('#fpSouth').value),east:Number($('#fpEast').value),west:Number($('#fpWest').value)};try{await api('/api/floorplans',{method:'POST',body:JSON.stringify(body)});toast('Floorplan registered','success');renderFloorplansPage()}catch(e){toast(e.message,'error')}}
async function toggleHeatmap(){if(state.heat){state.heat.remove();state.heat=null;return}try{const points=await api('/api/heatmap');state.heat=L.heatLayer(points,{radius:28,blur:22,maxZoom:18}).addTo(state.map);toast('Historical heatmap enabled','info')}catch(e){toast(e.message,'error')}}
function centerOnWorkers(){const pts=[...state.workers.values()].filter(w=>Number.isFinite(Number(w.lat))).map(w=>[w.lat,w.lng]);if(!pts.length)return toast('No worker coordinates available','info');state.map.fitBounds(pts,{padding:[30,30]})}
function connectSocket(){const socket=io();socket.on('connect',()=>setConnection(true,'LIVE'));socket.on('disconnect',()=>setConnection(false,'OFFLINE'));socket.on('snapshot',snap=>{snap.workers?.forEach(w=>state.workers.set(w.id,w));state.zones=snap.zones||state.zones;state.incidents=snap.incidents||state.incidents;renderAll()});socket.on('worker:update',w=>{state.workers.set(w.id,w);upsertMarker(w);renderStats();renderWorkerTable()});socket.on('worker:deleted',id=>{state.workers.delete(id);removeMarker(id);renderAll()});socket.on('worker:stale',x=>toast(`Worker ${x.workerId} telemetry is stale`,'warning'));socket.on('zone:created',z=>{if(!state.zones.some(x=>x.id===z.id))state.zones.unshift(z);renderZones();renderZonesPage()});socket.on('zone:deleted',id=>{state.zones=state.zones.filter(z=>z.id!==id);renderZones()});socket.on('incident:new',i=>{mergeIncident(i);renderStats();renderIncidentFeed();if(i.severity==='CRITICAL')toast(`CRITICAL: ${i.message}`,'error')});socket.on('incident:update',i=>{mergeIncident(i);renderAll()});socket.on('broadcast:new',b=>{state.broadcasts.unshift(b);showCommandOverlay(b)});socket.on('broadcast:ack',()=>{});socket.on('audit:new',()=>{});return socket}
function showCommandOverlay(b){const el=document.createElement('div');el.className=`command-overlay ${severityClass(b.priority)}`;el.innerHTML=`<div><span>COMMAND BROADCAST</span><strong>${esc(b.message)}</strong><button>ACKNOWLEDGE</button></div>`;el.querySelector('button').onclick=()=>el.remove();document.body.appendChild(el);if(b.priority==='CRITICAL')navigator.vibrate?.([200,100,200])}
function simulateDemoTelemetry(){if(state.demo){state.workers.forEach(w=>{if(!Number.isFinite(Number(w.lat)))return;const n={...w,lat:Number(w.lat)+(Math.random()-.5)*.00004,lng:Number(w.lng)+(Math.random()-.5)*.00004,altitudeM:(Number(w.altitudeM)||0)+(Math.random()-.5)*.25,heartRate:Math.round((Number(w.heartRate)||80)+(Math.random()-.5)*6),batteryPct:clamp((Number(w.batteryPct)||80)-.01,0,100),lastSeen:new Date().toISOString()};state.workers.set(w.id,n);upsertMarker(n)});renderWorkerTable()}}
function bindEvents(){setTheme(state.theme);$$('.nav').forEach(b=>b.onclick=()=>switchView(b.dataset.view));$$('[data-view]').forEach(b=>b.addEventListener('click',()=>switchView(b.dataset.view)));$('#themeBtn').onclick=()=>setTheme(state.theme==='night'?'day':'night');$('#drawZoneBtn').onclick=startZoneDrawing;$('#heatBtn').onclick=toggleHeatmap;$('#locateBtn').onclick=centerOnWorkers;$('#addWorkerBtn').onclick=openWorkerForm;$('#broadcastBtn').onclick=()=>{sendBroadcast($('#broadcastInput').value,$('#broadcastPriority').value);$('#broadcastInput').value=''};$('#demoBtn').onclick=()=>{state.demo=!state.demo;$('#demoBtn').classList.toggle('active',state.demo);toast(state.demo?'Local movement simulation enabled':'Simulation stopped',state.demo?'success':'info')};window.addEventListener('resize',()=>state.map?.invalidateSize())}
async function boot(){bindEvents();initMap();connectSocket();await loadAll();setInterval(async()=>{try{state.dashboard=await api('/api/dashboard');renderStats()}catch{}},5000);setInterval(simulateDemoTelemetry,2500);}
window.openWorker=openWorker;window.closeModal=closeModal;window.openWorkerForm=openWorkerForm;window.deleteWorker=deleteWorker;window.deleteZone=deleteZone;window.ackIncident=ackIncident;window.closeIncident=closeIncident;window.downloadReport=downloadReport;window.switchView=switchView;window.startZoneDrawing=startZoneDrawing;window.toggleHeatmap=toggleHeatmap;window.sendPageBroadcast=sendPageBroadcast;window.createFloorplan=createFloorplan;
document.addEventListener('DOMContentLoaded',boot);

// -----------------------------------------------------------------------------
// Worker-device telemetry adapter
// -----------------------------------------------------------------------------
// This adapter intentionally uses standard browser APIs only. A worker-facing
// mobile page can import this file and call startDeviceTelemetry(). The command
// center itself does not request location permission automatically.
async function sendTelemetry(payload){return api('/api/telemetry',{method:'POST',body:JSON.stringify(payload)})}
async function startDeviceTelemetry(workerId, options={}){
  if(!navigator.geolocation)throw new Error('Geolocation is not supported by this browser');
  const interval=Number(options.interval||5000); let timer=null; let stopped=false;
  const read=()=>new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,maximumAge:2000,timeout:10000}));
  const tick=async()=>{if(stopped)return;try{const p=await read();const payload={workerId,lat:p.coords.latitude,lng:p.coords.longitude,accuracyM:p.coords.accuracy,speedMps:p.coords.speed,headingDeg:p.coords.heading,altitudeM:p.coords.altitude,source:'PHONE_GPS'};await sendTelemetry(payload)}catch(e){console.warn('telemetry',e.message)}};
  await tick();timer=setInterval(tick,interval);return()=>{stopped=true;clearInterval(timer)};
}
window.startDeviceTelemetry=startDeviceTelemetry;window.sendTelemetry=sendTelemetry;
// -----------------------------------------------------------------------------
// Data-quality helpers
// -----------------------------------------------------------------------------
function telemetryQuality(t){const checks=[['GPS',Number.isFinite(Number(t.lat))&&Number.isFinite(Number(t.lng))],['Altitude',Number.isFinite(Number(t.altitudeM))],['HR',Number.isFinite(Number(t.heartRate))],['SpO2',Number.isFinite(Number(t.spo2))],['Battery',Number.isFinite(Number(t.batteryPct))]];return {score:Math.round(checks.filter(x=>x[1]).length/checks.length*100),checks}}
function workerRiskSummary(w){const risks=[];const st=workerStatus(w);if(st==='STALE'||st==='OFFLINE')risks.push('STALE_TELEMETRY');if(Number(w.spo2)<92)risks.push('LOW_SPO2');if(Number(w.heartRate)>=150)risks.push('HIGH_HEART_RATE');if(Number(w.batteryPct)<15)risks.push('LOW_BATTERY');return risks}
function getWorkerCoordinates(id){const w=state.workers.get(id);return w&&finite(Number(w.lat))?[Number(w.lat),Number(w.lng)]:null}
function finite(v){return Number.isFinite(Number(v))}
// -----------------------------------------------------------------------------
// Export a small public API for future modules / automated integration tests.
// -----------------------------------------------------------------------------
window.ALTIGUARD={state,api,sendTelemetry,startDeviceTelemetry,switchView,openWorker,downloadReport,telemetryQuality,workerRiskSummary,getWorkerCoordinates};
